insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_92_v1'
from (values
('127.735.d.1.A',3,'During a capstone course, a student revisits their career plan and adds a certification and an internship they still need. This is:','["improving a personal career plan with education, skills and experience", "abandoning the plan", "copying a classmate''s plan", "ignoring requirements"]'::jsonb,0,'Career plans are revised as goals clarify.','original'),
('127.735.d.1.A',4,'A career plan is stronger when it lists:','["only a job title", "specific education, job skills and experience needed for the goal", "only a salary guess", "nothing but dreams"]'::jsonb,1,'Concrete steps make the plan workable.','original'),
('127.735.d.1.B',3,'A resume for an IT job should be paired with letters of recommendation and:','["a blank page", "a list of hobbies only", "a portfolio of relevant work", "a game score"]'::jsonb,2,'Portfolios show proof of skills.','original'),
('127.735.d.1.B',4,'A student applying for a network technician role should tailor the resume by:','["listing every job ever held", "adding unrelated awards only", "leaving out experience", "highlighting skills and projects that match the chosen career plan"]'::jsonb,3,'Tailoring ties the resume to the target job.','original'),
('127.735.d.1.C',3,'At an interview for an IT help desk job, a strong candidate:','["answers clearly, gives examples and asks thoughtful questions", "interrupts the interviewer", "gives one-word answers", "avoids eye contact"]'::jsonb,0,'Good interviews show communication and preparation.','original'),
('127.735.d.1.C',4,'Before an IT interview, the best preparation is to:','["skip research", "research the company and rehearse answers with examples", "memorize a random script", "arrive late on purpose"]'::jsonb,1,'Preparation shows interest and skill.','original'),
('127.735.d.2.A',3,'An IT team lead emails a status report, gives a short verbal briefing and shows a diagram of the network. This uses:','["silence", "only written communication", "written, verbal and visual communication", "only gestures"]'::jsonb,2,'IT work blends communication forms.','original'),
('127.735.d.2.A',4,'In IT industry standards, a written change request should be:','["full of jokes", "vague and short", "written in code only", "clear, accurate and complete"]'::jsonb,3,'Standards demand clarity.','original'),
('127.735.d.2.B',3,'A technician calculates how many gigabytes are needed for 40 users at 25 GB each. This uses:','["mathematics in developing a service", "art skills", "cooking skills", "music skills"]'::jsonb,0,'Math supports capacity planning.','original'),
('127.735.d.2.B',4,'A service plan needs 4 servers at 2.5 TB each. Total storage needed is:','["1.6 TB", "10 TB", "100 TB", "6.5 TB"]'::jsonb,1,'4 × 2.5 TB = 10 TB.','original'),
('127.735.d.2.C',3,'Choosing a fan and heat sink so a server stays cool relies on:','["only box size", "only paint color", "science principles about heat transfer", "only logo placement"]'::jsonb,2,'Thermal science guides cooling design.','original'),
('127.735.d.2.C',4,'An IT designer knows that electrical resistance produces heat. This science principle affects the design of:','["printer paper", "font choices", "email subject lines", "cooling and power systems"]'::jsonb,3,'Resistance and heat drive power and cooling design.','original'),
('127.735.d.3.A',3,'A capstone student notices employees keep losing files because backups fail. Naming that issue is:','["identifying a problem relating to information technology", "solving the problem", "ignoring the problem", "publishing the solution"]'::jsonb,0,'Problem identification starts the process.','original'),
('127.735.d.3.A',4,'A clear problem statement for a capstone project should be:','["vague and broad", "specific, measurable and focused on an IT need", "already solved", "unrelated to technology"]'::jsonb,1,'Good statements focus the research.','original'),
('127.735.d.3.B',3,'A researcher starts with the overall system, then breaks it into smaller parts. This is a:','["random approach", "bottom-up approach", "top-down approach", "backward approach"]'::jsonb,2,'Top-down begins with the big picture.','original'),
('127.735.d.3.B',4,'A researcher who first studies individual components and then builds toward the whole system uses a:','["hybrid ignoring parts", "top-down approach", "one-step approach", "bottom-up approach"]'::jsonb,3,'Bottom-up starts with components.','original'),
('127.735.d.4.A',3,'After weighing options for a failing backup system, the team picks a solution using resources, IT concepts and industry standards. This is applying:','["critical-thinking strategies to develop a solution", "guessing", "ignoring data", "copying"]'::jsonb,0,'Critical thinking builds sound solutions.','original'),
('127.735.d.4.A',4,'A critical thinker evaluating a proposed IT fix will:','["accept the first idea", "check evidence, alternatives and standards before deciding", "rely on opinion", "ignore standards"]'::jsonb,1,'Evidence guides decisions.','original'),
('127.735.d.4.B',3,'A team uses a weighted decision matrix to choose between three backup products. This is a:','["security breach", "delay tactic", "decision-making technique", "design flaw"]'::jsonb,2,'Decision matrices compare options.','original'),
('127.735.d.4.B',4,'Which criterion belongs in a decision matrix for selecting a backup solution?','["logo size", "the vendor''s slogan", "paint color", "cost, reliability and ease of use"]'::jsonb,3,'Criteria should relate to needs.','original'),
('127.735.d.4.C',3,'To justify a new backup system to management, the student explains:','["how it will resolve the problem", "nothing", "only its price tag", "only its color"]'::jsonb,0,'Explanations link solution to problem.','original'),
('127.735.d.4.C',4,'A good explanation of a proposed solution connects:','["only the cost", "the solution''s features to the problem''s causes", "unrelated features", "random facts"]'::jsonb,1,'Clear logic persuades.','original'),
('127.735.d.5.A',3,'Throughout the capstone, the student meets regularly with an industry expert who reviews the design. This is:','["working alone", "avoiding feedback", "working closely with a mentor", "changing mentors daily"]'::jsonb,2,'Mentors guide design and implementation.','original'),
('127.735.d.5.A',4,'The biggest benefit of mentor feedback during implementation is that it:','["eliminates testing", "replaces all work", "removes deadlines", "catches mistakes early and improves quality"]'::jsonb,3,'Mentors improve results.','original'),
('127.735.d.5.B',3,'A student builds a small client-ticketing app to meet a specified need using a problem-solving strategy. This is:','["developing a product to meet a need", "avoiding design", "copying a product", "deleting a plan"]'::jsonb,0,'Needs drive product design.','original'),
('127.735.d.5.B',4,'A problem-solving strategy used in product development includes defining the problem, planning, building and:','["ending early", "testing and refining the solution", "skipping review", "hiding the product"]'::jsonb,1,'Test and refine completes the loop.','original'),
('127.735.d.5.C',3,'Adding input validation and a backup power supply to a service are ways to design in:','["delay", "clutter", "quality, reliability and safety", "cost only"]'::jsonb,2,'Features can be designed for these goals.','original'),
('127.735.d.5.C',4,'Which feature improves the reliability of a database service?','["a brighter logo", "fewer log files", "removing monitoring", "automatic failover to a second server"]'::jsonb,3,'Failover keeps service available.','original'),
('127.735.d.5.D',3,'A security management plan for a capstone product lists:','["security requirements and how they will be met", "only meeting times", "only the product name", "random notes"]'::jsonb,0,'Plans address requirements with actions.','original'),
('127.735.d.5.D',4,'Implementing a security management plan includes:','["ignoring risks", "assigning controls, monitoring and reviewing them", "writing only policy titles", "sharing passwords"]'::jsonb,1,'Plans must be carried out and reviewed.','original'),
('127.735.d.5.E',3,'A sustainability plan describes how the product or service will:','["end next week", "avoid updates", "continue to operate and be maintained over time", "hide costs"]'::jsonb,2,'Sustainability looks ahead.','original'),
('127.735.d.5.E',4,'Which item belongs in a sustainability plan for a service?','["a logo draft", "a staff birthday list", "a list of favorite colors", "a schedule for updates, support and funding"]'::jsonb,3,'Long-term support is essential.','original'),
('127.735.d.5.F',3,'To learn whether clients are happy with a new service, the student creates a short survey. This is part of:','["an evaluation method for client satisfaction", "a hardware repair", "a license purchase", "a design flaw"]'::jsonb,0,'Surveys measure satisfaction.','original'),
('127.735.d.5.F',4,'An evaluation method for a service should measure its effect on client satisfaction and:','["only the logo", "whether the original problem was solved", "only the font", "only the price"]'::jsonb,1,'Evaluation checks outcomes.','original'),
('127.735.d.5.G',3,'A project portfolio that documents research and development shows:','["nothing", "only the final grade", "how the project progressed from idea to product", "only photographs"]'::jsonb,2,'Portfolios record the process.','original'),
('127.735.d.5.G',4,'Which belongs in a project portfolio of research and development?','["unrelated games", "only a title page", "blank pages", "research notes, design drafts, test results and the final product"]'::jsonb,3,'Complete documentation tells the story.','original'),
('127.735.d.5.H',3,'Presenting the portfolio to a panel of professionals calls for:','["formal presentation skills", "avoiding questions", "reading silently", "casual chatting only"]'::jsonb,0,'Panels expect polished delivery.','original'),
('127.735.d.5.H',4,'A strong formal presentation includes a clear introduction, organized content and:','["a joke only", "a response to the panel''s questions", "a rush to finish", "a silent exit"]'::jsonb,1,'Handling questions shows mastery.','original'),
('127.735.d.6.A',3,'A student collects transcripts, volunteer hours, certificates and work experience into one folder for job applications. This is:','["deleting records", "hiding records", "creating a portfolio documenting accomplishments", "losing records"]'::jsonb,2,'Portfolios gather proof of accomplishments.','original'),
('127.735.d.6.A',4,'A career portfolio should include evidence of:','["only passwords", "only game scores", "only social posts", "academics, volunteer work, employment and certifications"]'::jsonb,3,'Breadth shows readiness.','original'),
('127.735.d.6.B',3,'A student puts the most relevant projects first and groups related items together. This is:','["organizing and prioritizing portfolio information", "scrambling it", "deleting it", "hiding it"]'::jsonb,0,'Organization helps reviewers.','original'),
('127.735.d.6.B',4,'Which approach best prioritizes portfolio content for a cybersecurity job?','["Hide the projects", "Put security projects and certifications first", "Put unrelated photos first", "Put hobbies first"]'::jsonb,1,'Relevance guides priority.','original'),
('127.735.d.6.C',3,'A portfolio cover letter, a slide deck and a short demo video show:','["only voice", "only one type of communication", "written, verbal and visual communication", "no communication"]'::jsonb,2,'Portfolios use all three forms.','original'),
('127.735.d.6.C',4,'Industry-standard communication in a portfolio means writing that is:','["sloppy", "slang-heavy", "unreadable", "clear, professional and organized"]'::jsonb,3,'Standards demand professionalism.','original'),
('127.736.d.1.A',3,'During an advanced practicum, a student summarizes a server upgrade in a memo, explains it aloud to the team and shows a before-and-after diagram. These are:','["written, verbal and visual communication in IT", "no communication", "one type of communication", "only body language"]'::jsonb,0,'Practicum work requires all three.','original'),
('127.736.d.1.A',4,'Following IT industry standards for communication means a report is:','["casual and unorganized", "accurate, organized and appropriate for its audience", "only graphics", "only slang"]'::jsonb,1,'Standards focus on clarity.','original'),
('127.736.d.1.B',3,'During an advanced practicum, a technician repeats a client''s problem back in different words to be sure it was understood. This is:','["ignoring", "guessing", "active listening to clarify information", "interrupting"]'::jsonb,2,'Active listening confirms understanding.','original'),
('127.736.d.1.B',4,'In a practicum client meeting, which behavior shows active listening?','["interrupting often", "looking away", "checking a phone", "Asking follow-up questions and summarizing what was said"]'::jsonb,3,'Questions and summaries demonstrate listening.','original'),
('127.736.d.1.C',3,'A student delivers a formal slide presentation to executives and an informal update to teammates. This is:','["delivering formal and informal presentations effectively", "skipping the audience", "reading blindly", "avoiding presenting"]'::jsonb,0,'Effective presenters adapt to audience.','original'),
('127.736.d.1.C',4,'An effective presentation to non-technical executives should:','["use unexplained jargon", "use plain language and focus on business impact", "hide the results", "skip visuals"]'::jsonb,1,'Match the message to the audience.','original'),
('127.736.d.1.D',3,'A technician thanks a client for patience and explains next steps for an outage. This is:','["poor service", "avoiding contact", "public relations skills that maintain customer satisfaction", "ignoring the client"]'::jsonb,2,'PR builds trust.','original'),
('127.736.d.1.D',4,'Maintaining satisfaction with an internal customer, like another department, includes:','["delaying replies", "ignoring requests", "blaming them", "timely updates and respectful communication"]'::jsonb,3,'Internal clients deserve good service too.','original'),
('127.736.d.2.A',3,'A team splits a complex outage into smaller causes, tests each one, and shares ideas as they go. This shows:','["critical-thinking skills used alone and in groups", "random guessing", "blame shifting", "avoiding the problem"]'::jsonb,0,'Structured thinking solves problems.','original'),
('127.736.d.2.A',4,'Employing critical thinking with increased fluency means the student can:','["avoid analysis", "analyze problems quickly and accurately without step-by-step help", "ignore evidence", "need help for every step"]'::jsonb,1,'Fluency shows mastery.','original'),
('127.736.d.2.B',3,'Given three possible fixes, the student evaluates each against requirements and picks one. This is:','["copying", "flipping a coin", "applying critical-thinking strategies to develop a solution", "skipping evaluation"]'::jsonb,2,'Evaluation drives solution choice.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_92_v1'
from (values
('127.736.d.2.B',4,'Using appropriate technologies and standards when developing a solution means the solution:','["ignores standards", "avoids resources", "uses random tools", "fits the problem and meets industry expectations"]'::jsonb,3,'Right tools and standards produce good solutions.','original'),
('127.736.d.2.C',3,'A team chooses between a cloud service and on-site hardware using a comparison chart of cost, security and support. This is:','["a decision-making technique", "a coin toss", "avoidance", "a guess"]'::jsonb,0,'Charts support choices.','original'),
('127.736.d.2.C',4,'Making a technology-based decision with increased fluency includes:','["avoiding data", "weighing criteria and justifying the choice", "picking at random", "deleting options"]'::jsonb,1,'Justified choices show mastery.','original'),
('127.736.d.3.A',3,'A student locks the server room, logs out of shared PCs and follows password rules. This is:','["sharing passwords", "ignoring policies", "consistently following IT security rules and procedures", "disabling alarms"]'::jsonb,2,'Security rules protect assets.','original'),
('127.736.d.3.A',4,'Following IT security regulations includes:','["sharing credentials", "bypassing controls", "hiding incidents", "complying with required controls and reporting violations"]'::jsonb,3,'Compliance protects the organization.','original'),
('127.736.d.3.B',3,'A security management plan for a small office lists threats, controls and who is responsible. Implementing it means:','["carrying out and reviewing those controls", "hiding it", "deleting it", "filing it unread"]'::jsonb,0,'Plans must be implemented.','original'),
('127.736.d.3.B',4,'A security management plan should be updated when:','["only each decade", "new threats or system changes appear", "never", "only when a manager asks"]'::jsonb,1,'Plans adapt to risks.','original'),
('127.736.d.4.A',3,'A student arrives on time and completes assigned tasks carefully without needing reminders. This shows:','["avoidance", "a poor attitude", "a positive, productive work ethic", "procrastination"]'::jsonb,2,'Reliability reflects work ethic.','original'),
('127.736.d.4.A',4,'Performing tasks as directed means:','["doing only what you like", "skipping steps", "ignoring deadlines", "following instructions and finishing the work properly"]'::jsonb,3,'Directed work demonstrates dependability.','original'),
('127.736.d.4.B',3,'An IT worker keeps client data private as required by law and company policy. This is:','["practicing ethical and legal responsibilities", "ignoring duties", "sharing secrets", "avoiding rules"]'::jsonb,0,'IT professionals protect data.','original'),
('127.736.d.4.B',4,'Which is an ethical responsibility in IT?','["hiding breaches", "protecting user privacy and reporting vulnerabilities", "using pirated software", "selling private data"]'::jsonb,1,'Ethics guide professional conduct.','original'),
('127.736.d.4.C',3,'A technician finds an error that would make them look bad but reports it anyway. This shows:','["dishonesty", "carelessness", "integrity in choosing the ethical course", "avoidance"]'::jsonb,2,'Integrity means doing right.','original'),
('127.736.d.4.C',4,'Choosing the ethical course when pressured to hide a security mistake means:','["deleting logs", "covering it up", "blaming a coworker", "reporting it honestly"]'::jsonb,3,'Honesty is ethical.','original'),
('127.736.d.4.D',3,'An IT employee follows software licensing laws and company rules every time. This is:','["complying with applicable rules and laws consistently", "breaking rules when convenient", "ignoring laws", "hiding violations"]'::jsonb,0,'Consistent compliance is professional.','original'),
('127.736.d.4.D',4,'Consistent compliance with rules matters in IT because violations can lead to:','["higher grades", "legal penalties and loss of trust", "faster networks", "free equipment"]'::jsonb,1,'Violations have consequences.','original'),
('127.736.d.5.A',3,'A student designs and implements a ticket-tracking tool that meets a stated need for a small business. This is:','["copying a product", "dropping the project", "creating a product that addresses a specified need", "avoiding design"]'::jsonb,2,'Products start from needs.','original'),
('127.736.d.5.A',4,'A product developed in a practicum is successful when it:','["is finished fastest", "is the fanciest", "uses the most code", "solves the identified problem and meets the client''s need"]'::jsonb,3,'Success is measured against need.','original'),
('127.736.d.5.B',3,'Adding automated tests and a surge protector to a deployment helps build in:','["quality, reliability and safety", "clutter", "delays", "cost only"]'::jsonb,0,'Design choices can improve quality and safety.','original'),
('127.736.d.5.B',4,'Which choice best improves the safety of a data center''s design?','["more clutter", "fire suppression and proper cable management", "fewer exits", "unlabeled cables"]'::jsonb,1,'Safety is designed in.','original'),
('127.736.d.5.C',3,'A sustainability plan for a deployed app explains how it will be:','["abandoned", "hidden", "maintained, updated and supported over time", "deleted"]'::jsonb,2,'Sustainability extends life.','original'),
('127.736.d.5.C',4,'Planning for future staffing and funding for a service is part of its:','["title page", "timeline cover", "logo", "sustainability plan"]'::jsonb,3,'Resources keep services going.','original'),
('127.736.d.5.D',3,'A student measures how client satisfaction changes after launching a service using surveys and ticket counts. This is:','["an evaluation method for the service''s effect", "a delay", "a guess", "a design flaw"]'::jsonb,0,'Evaluation uses data.','original'),
('127.736.d.5.D',4,'A good evaluation method analyzes client satisfaction and:','["the printer brand", "whether the problem was actually solved", "the font", "the logo color"]'::jsonb,1,'Evaluate outcomes.','original'),
('127.736.d.5.E',3,'A student saves a finished app, a design document and a test report as examples of their practicum. These are:','["draft notes only", "deleted items", "representative work samples", "unrelated files"]'::jsonb,2,'Work samples demonstrate skills.','original'),
('127.736.d.5.E',4,'Representative work samples should show:','["only drafts", "only mistakes", "only unrelated items", "the student''s best and most relevant work"]'::jsonb,3,'Samples represent ability.','original'),
('127.737.d.1.A',3,'A computer technology student adds a CompTIA certification and a repair internship to her personal career plan. This is:','["improving a career plan with education, skills and experience", "abandoning the plan", "ignoring goals", "skipping training"]'::jsonb,0,'Plans grow with goals.','original'),
('127.737.d.1.A',4,'A realistic plan for becoming a computer repair technician includes:','["no steps", "needed training, certifications and hands-on experience", "only a job title", "only a salary"]'::jsonb,1,'Concrete steps lead to goals.','original'),
('127.737.d.1.B',3,'A resume for a hardware technician job includes letters of recommendation and:','["a blank page", "only game scores", "relevant skills, certifications and work experience", "only hobbies"]'::jsonb,2,'Resumes show qualifications.','original'),
('127.737.d.1.B',4,'A strong recommendation letter for an IT job should come from:','["an anonymous source", "a friend who never saw the work", "a stranger", "a teacher or employer who knows the student''s work"]'::jsonb,3,'Credible recommenders strengthen a resume.','original'),
('127.737.d.1.C',3,'In a mock interview for a field technician role, the best answer to "Tell me about a problem you solved" is:','["a specific example with the steps taken and the result", "a refusal", "a joke", "a vague claim"]'::jsonb,0,'Examples prove skills.','original'),
('127.737.d.1.C',4,'After an interview, a candidate should:','["complain about the process", "send a brief thank-you message", "avoid contact", "never follow up"]'::jsonb,1,'Follow-up shows professionalism.','original'),
('127.737.d.2.A',3,'A technician explains a repair politely to a customer who speaks a different first language, using simple words and clear gestures. This is:','["rudeness", "avoidance", "effective communication with people from varied cultures", "poor service"]'::jsonb,2,'Respectful communication bridges cultures.','original'),
('127.737.d.2.A',4,'When communicating with a coworker from a different cultural background, a good practice is to:','["talk loudly and fast", "assume they agree", "ignore their input", "speak clearly and respectfully and check for understanding"]'::jsonb,3,'Clarity and respect help everyone.','original'),
('127.737.d.2.B',3,'After a printer installation, the technician fills out a work order with the date, work done and parts used. This is:','["completing work orders and related paperwork", "skipping documentation", "hiding records", "deleting records"]'::jsonb,0,'Work orders document service.','original'),
('127.737.d.2.B',4,'Why must a technician complete accurate paperwork after a repair?','["It slows the repair", "It records what was done for billing and future service", "It hides mistakes", "It''s unnecessary"]'::jsonb,1,'Records support billing and follow-up.','original'),
('127.737.d.2.C',3,'A technician adds up parts costs and labor hours to give a customer a price before beginning an installation. This is:','["avoiding pricing", "refusing service", "estimating supplies, materials and labor costs", "guessing wildly"]'::jsonb,2,'Estimates inform customers.','original'),
('127.737.d.2.C',4,'A job needs 3 hours of labor at $40/hour and $85 in parts. The estimate is:','["$340", "$125", "$165", "$205"]'::jsonb,3,'3 × 40 = 120; 120 + 85 = 205.','original'),
('127.737.d.2.D',3,'A technician reads a wiring schematic to find where a cable should connect. This is:','["reading and interpreting technical documentation", "guessing", "ignoring diagrams", "avoiding manuals"]'::jsonb,0,'Schematics guide installations.','original'),
('127.737.d.2.D',4,'To troubleshoot a power supply fault, the best document to consult is:','["a poster", "the manufacturer''s technical manual or schematic", "a menu", "a map"]'::jsonb,1,'Manuals contain correct specs.','original'),
('127.737.d.3.A',3,'A project lead writes a status email, briefs the team aloud and shares a network diagram. This uses:','["only gestures", "no communication", "written, verbal and visual IT communication", "one type only"]'::jsonb,2,'IT work uses all three.','original'),
('127.737.d.3.A',4,'An email to a client about a scheduled maintenance outage should follow IT communication standards by being:','["slang-filled", "vague", "rambling", "clear, concise and professional"]'::jsonb,3,'Standards promote clarity.','original'),
('127.737.d.3.B',3,'A technician converts 2.4 GHz into hertz while sizing a wireless network. This uses:','["mathematics in developing a service", "cooking", "art", "music"]'::jsonb,0,'Unit conversions support IT work.','original'),
('127.737.d.3.B',4,'A network needs 24 ports per switch and 5 switches. The total number of ports is:','["29", "120", "100", "240"]'::jsonb,1,'24 × 5 = 120.','original'),
('127.737.d.3.C',3,'Choosing a cable type to reduce electrical interference applies:','["only cable color", "only box size", "science principles about electromagnetic fields", "only logo"]'::jsonb,2,'Interference is a science concept.','original'),
('127.737.d.3.C',4,'Knowing that metal conducts electricity helps a technician to:','["paint equipment", "hide equipment", "rename equipment", "ground equipment safely"]'::jsonb,3,'Science guides safe design.','original'),
('127.737.d.4.A',3,'The microprocessor is often called the brain of the computer because it:','["executes instructions and processes data", "stores long-term files only", "cools the case", "prints documents"]'::jsonb,0,'The processor runs instructions.','original'),
('127.737.d.4.A',4,'Microprocessor theory says the processor works in a repeating cycle of:','["draw, paint and erase", "fetch, decode and execute", "type, save and quit", "print, copy and fold"]'::jsonb,1,'The instruction cycle is fetch-decode-execute.','original'),
('127.737.d.4.B',3,'Boolean logic uses operations such as AND, OR and NOT to:','["store music", "print pages", "combine true and false values", "draw images"]'::jsonb,2,'Boolean logic underlies computer decisions.','original'),
('127.737.d.4.B',4,'In Boolean logic, an AND gate receives a 1 and a 0 on its two inputs. Its output is:','["undefined", "1", "2", "0"]'::jsonb,3,'AND is true only if both inputs are true.','original'),
('127.737.d.4.C',3,'A computer''s circuits depend on electric current, which is the flow of:','["electrons", "light only", "water", "sound"]'::jsonb,0,'Electricity is the flow of electrons.','original'),
('127.737.d.4.C',4,'A theory of magnetism is used in a computer''s hard disk drive to:','["print pages", "store data as magnetic patterns", "cool the case", "amplify sound"]'::jsonb,1,'HDDs record data magnetically.','original'),
('127.737.d.4.D',3,'A technician starts by asking the user what changed, then isolates the issue and tests a fix. This is:','["avoidance", "random changes", "a proper troubleshooting technique", "blaming the user"]'::jsonb,2,'Methodical troubleshooting finds causes.','original'),
('127.737.d.4.D',4,'A common troubleshooting rule is to change:','["nothing", "everything randomly", "many things at once", "one thing at a time and test after each change"]'::jsonb,3,'One change at a time shows what worked.','original'),
('127.737.d.4.E',3,'A signal that varies continuously, like a voice recorded by a microphone, is:','["analog", "digital", "packet", "binary"]'::jsonb,0,'Analog signals are continuous.','original'),
('127.737.d.4.E',4,'A digital signal represents data using:','["sound only", "discrete values such as 0 and 1", "random noise", "a continuous wave only"]'::jsonb,1,'Digital uses discrete values.','original')
